package br.com.amcash.operationalcost.controller;
import br.com.amcash.config.*; import br.com.amcash.operationalcost.dto.request.*; import br.com.amcash.operationalcost.dto.response.*; import br.com.amcash.operationalcost.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/operational-costs")
public class OperationalCostController {
    private final OperationalCostService service; private final OperationalMileageSuggestionService mileageSuggestions; public OperationalCostController(OperationalCostService service,OperationalMileageSuggestionService mileageSuggestions){this.service=service;this.mileageSuggestions=mileageSuggestions;}
    @GetMapping public List<OperationalCostResponse> list(@CurrentUser AuthenticatedUser user){return service.list(user.userId());}
    @GetMapping("/vehicles/{vehicleId}") public OperationalCostResponse get(@CurrentUser AuthenticatedUser user,@PathVariable UUID vehicleId){return service.get(user.userId(),vehicleId);}
    @PostMapping("/vehicles/{vehicleId}") @ResponseStatus(HttpStatus.CREATED) public OperationalCostResponse create(@CurrentUser AuthenticatedUser user,@PathVariable UUID vehicleId,@Valid @RequestBody OperationalCostRequest request){return service.create(user.userId(),vehicleId,request);}
    @PutMapping("/vehicles/{vehicleId}") public OperationalCostResponse update(@CurrentUser AuthenticatedUser user,@PathVariable UUID vehicleId,@Valid @RequestBody OperationalCostRequest request){OperationalCostResponse previous=service.get(user.userId(),vehicleId);OperationalCostResponse response=service.update(user.userId(),vehicleId,request);if(previous.monthlyMileage().compareTo(request.monthlyMileage())!=0)mileageSuggestions.configurationChanged(user.userId(),vehicleId,request.mileageSource());return response;}
    @PatchMapping("/vehicles/{vehicleId}/monthly-mileage") public OperationalCostResponse updateMileage(@CurrentUser AuthenticatedUser user,@PathVariable UUID vehicleId,@Valid @RequestBody OperationalMileageUpdateRequest request){OperationalCostResponse response=service.updateMileage(user.userId(),vehicleId,request);mileageSuggestions.configurationChanged(user.userId(),vehicleId,request.mileageSource());return response;}
    @GetMapping("/vehicles/{vehicleId}/mileage-suggestions") public MileageSuggestionsResponse mileageSuggestions(@CurrentUser AuthenticatedUser user,@PathVariable UUID vehicleId){return mileageSuggestions.suggestions(user.userId(),vehicleId);}
    @PatchMapping("/vehicles/{vehicleId}/mileage-suggestions/{source}/dismiss") @ResponseStatus(HttpStatus.NO_CONTENT) public void dismissMileageSuggestion(@CurrentUser AuthenticatedUser user,@PathVariable UUID vehicleId,@PathVariable br.com.amcash.operationalcost.entity.MileageSource source){mileageSuggestions.dismiss(user.userId(),vehicleId,source);}
    @DeleteMapping("/vehicles/{vehicleId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@CurrentUser AuthenticatedUser user,@PathVariable UUID vehicleId){service.delete(user.userId(),vehicleId);}
}
